export type OpName = keyof OpArgs;

// The data of a topic's snap and delta messages, by topic name.
export interface TopicData {
  "status": { snap: StatusSnap; delta: StatusSnap };
  "toasts": { snap: ToastsSnap; delta: ToastsDelta };
  "chats": { snap: ChatsSnap; delta: ChatsDelta };
  "chat": { snap: ChatSnap; delta: ChatDelta };
  "cards": { snap: CardsSnap; delta: CardsDelta };
  "tree": { snap: TreeSnap; delta: TreeDirDelta | TreeRemoveDelta | TreeHiddenDelta };
  "bufs": { snap: BufsSnap; delta: BufsSnap };
  "buf": { snap: BufSnap; delta: LinesDelta | TickDelta | DirtyDelta | ResetDelta | GoneDelta };
  "terms": { snap: TermsSnap; delta: TermsSnap };
  "term": { snap: TermSnap; delta: LinesDelta | TickDelta | TermResetDelta | TermModeDelta | GoneDelta };
  "git": { snap: GitSnap; delta: GitSnap };
  "tasks": { snap: TasksSnap; delta: TasksSnap };
  "runs": { snap: RunsSnap; delta: RunsSnap };
  "mcp": { snap: MCPSnap; delta: MCPSnap };
  "settings": { snap: SettingsSnap; delta: SettingsSnap };
  "diagnostics": { snap: DiagSnap; delta: DiagSnap };
  "tests": { snap: TestsSnap; delta: TestsSnap };
  "debug": { snap: DebugSnap; delta: DebugSnap };
  "services": { snap: ServicesSnap; delta: ServicesSnap };
}

// The data of an ev message, by kind.
export interface EventData {
  "answered": Answered;
  "attention": Attention;
  "search.batch": SearchBatch;
}

